"""
Execution-grounded verification of agent-authored workspaces.

Five gates, each of which either runs the code or performs AST analysis on it:

    syntax     Every authored .py file must parse (`ast.parse`). Empty
               workspaces (0 Python files) return `FAILED`.
    build      Packaging metadata (`pyproject.toml`, `setup.py`, or `setup.cfg`)
               must exist and be valid/installable. When `pyproject.toml` is
               present, validate it with `tomllib` (must parse as valid TOML and
               contain at least one of `[project]`, `[build-system]`, or
               `[tool]` tables; an empty or malformed `pyproject.toml` returns
               `FAILED`), and run `pip install -e . --no-deps --no-build-isolation`
               when `pip` is available.
    smoke      Non-test authored modules must import in a subprocess with both
               `workdir` and `os.path.join(workdir, "src")` on `PYTHONPATH`. If
               no importable modules exist or any module fails with a syntax or
               runtime error, return `FAILED`. If module imports fail solely
               with `ModuleNotFoundError` for uninstalled third-party packages
               (e.g. `opentelemetry`), return `SKIPPED` (not `FAILED`).
    tests      Discover test files (`"test" in os.path.basename(p).lower()`;
               if none exist, return `FAILED`) and run them with both `workdir`
               and `os.path.join(workdir, "src")` on `PYTHONPATH`. Use `pytest`
               if installed in `self.python`; otherwise run a stdlib fallback
               subprocess that imports each test file and collects/executes BOTH
               bare `def test_*()` functions (taking 0 required args) AND
               `unittest.TestCase` subclasses (because `unittest discover`
               ignores bare `def test_*()` functions). If 0 tests are collected
               because of `ModuleNotFoundError` for an uninstalled third-party
               package, return `SKIPPED`.
    telemetry  AST analysis of authored `.py` files must find BOTH (1) an actual
               `import opentelemetry` or `from opentelemetry ... import ...`
               node AND (2) at least one AST `Call` to a tracer/span method or
               function (`start_as_current_span`, `start_span`, `get_tracer`,
               `get_tracer_provider`, `set_tracer_provider`, `get_meter`). A
               comment/docstring mention or a bare `import opentelemetry`
               without any tracer/span call must return `FAILED`.

Each result carries the `method` used to reach it. A gate that could not be
evaluated returns `SKIPPED` rather than `PASSED`, so a missing tool can never be
mistaken for a success, and `SKIPPED` gates are excluded from the fitness
denominator (`evaluated_gates` and `score_penalty`) rather than scored as
failures (`score_penalty = failed_gate_count * penalty_per_gate`).

The V1 verifier this replaces executed nothing in three of its four gates:
`build` was a filename substring match, `smoke` was `len(files) >= 3`, and
`telemetry` searched text that included the CEO's markdown prose, so an essay
mentioning OpenTelemetry passed. Six generations were selected on those
signals. The whole design rule here is that no gate may be satisfiable by
writing about it.

Usage:
    from hae.evaluation.harness import ExecutionHarness

    harness = ExecutionHarness()
    report = harness.verify_workspace(workspace, deliverable_text)
    print(report.summary(), report.gate_status)
"""

import ast
import os
import re
import subprocess
import sys
import tempfile
import time
import shutil
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

# Try to import tomllib (Python 3.11+) or tomli (fallback)
try:
    import tomllib
except ImportError:
    try:
        import tomli as tomllib
    except ImportError:
        tomllib = None

from hae.evaluation.artifacts import filter_bundle, count_source_files

SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED

@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = []
        lines.append(f"Verification Report ({self.source})")
        lines.append(f"Authored files: {self.authored_files}, Python files: {self.python_files}")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("Gates:")
        for g in self.gates:
            status_str = g.status.upper()
            lines.append(f"  [{status_str}] {g.name}: {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "gate_status": self.gate_status,
            "pass_rate": self.pass_rate
        }

def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to match fenced code blocks with optional language and optional filename
    # Pattern: ```[language] [filename]\n(content)\n```
    # We look for lines starting with ``` followed by optional word (lang) and optional path
    pattern = r"```(?:\w+)?\s+([^\n]+)\n(.*?)```"
    matches = re.findall(pattern, text, re.DOTALL)

    bundle = {}
    for path, content in matches:
        # Clean up path: strip whitespace, remove leading/trailing quotes if any
        clean_path = path.strip().strip('"').strip("'")
        if clean_path:
            bundle[clean_path] = content

    return bundle

class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int=DEFAULT_TIMEOUT_S, penalty_per_gate: float=DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str]=None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python = python_executable or sys.executable

    def verify_workspace(self, workspace: Any=None, deliverable_text: str='') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            try:
                if hasattr(workspace, 'export_bundle'):
                    bundle = workspace.export_bundle()
                    source = 'workspace'
                elif hasattr(workspace, 'files'):
                    # Assume it's a dict-like or has a files attribute
                    if isinstance(workspace.files, dict):
                        bundle = workspace.files
                        source = 'workspace'
            except Exception:
                pass

        # Fallback to deliverable text if bundle is empty
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str='bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter out generated/malformed paths
        filtered_bundle = filter_bundle(bundle)

        # Count files
        authored_files = len(filtered_bundle)
        python_files = count_source_files(filtered_bundle, suffixes=('.py',))

        if authored_files == 0:
            # Empty workspace
            gates = [
                GateResult(name='syntax', status=FAILED, method='count', detail='No authored files found.'),
                GateResult(name='build', status=FAILED, method='count', detail='No authored files found.'),
                GateResult(name='smoke', status=FAILED, method='count', detail='No authored files found.'),
                GateResult(name='tests', status=FAILED, method='count', detail='No authored files found.'),
                GateResult(name='telemetry', status=FAILED, method='count', detail='No authored files found.'),
            ]
            failed_count = sum(1 for g in gates if g.status == FAILED)
            return VerificationReport(
                gates=gates,
                score_penalty=failed_count * self.penalty_per_gate,
                authored_files=0,
                python_files=0,
                source=source
            )

        # Create temp dir and write files
        with tempfile.TemporaryDirectory() as tmpdir:
            for path, content in filtered_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=filtered_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]]=None, source: str='directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory for authored files
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Skip hidden dirs and common junk
                dirs[:] = [d for d in dirs if not d.startswith('.') and d not in ('__pycache__', 'venv', '.venv', '.git')]
                for file in files:
                    if file.endswith('.py'):
                        rel_path = os.path.relpath(os.path.join(root, file), workdir)
                        # Normalize path separators
                        rel_path = rel_path.replace('\\', '/')
                        if not rel_path.startswith('.'):
                            try:
                                with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                                    authored[rel_path] = f.read()
                            except Exception:
                                pass

        authored_files = len(authored)
        python_files = count_source_files(authored, suffixes=('.py',))

        gates = []

        # 1. Syntax Gate
        start = time.time()
        syntax_result = self._check_syntax(workdir, authored)
        syntax_result.duration_s = time.time() - start
        gates.append(syntax_result)

        # 2. Build Gate
        start = time.time()
        build_result = self._check_build(workdir, authored)
        build_result.duration_s = time.time() - start
        gates.append(build_result)

        # 3. Smoke Gate
        start = time.time()
        smoke_result = self._check_smoke(workdir, authored)
        smoke_result.duration_s = time.time() - start
        gates.append(smoke_result)

        # 4. Tests Gate
        start = time.time()
        tests_result = self._check_tests(workdir, authored)
        tests_result.duration_s = time.time() - start
        gates.append(tests_result)

        # 5. Telemetry Gate
        start = time.time()
        telemetry_result = self._check_telemetry(workdir, authored)
        telemetry_result.duration_s = time.time() - start
        gates.append(telemetry_result)

        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source
        )

    def _check_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        py_files = {p: c for p, c in authored.items() if p.endswith('.py')}
        if not py_files:
            return GateResult(name='syntax', status=FAILED, method='ast.parse', detail='No Python files to parse.')

        errors = []
        for path, content in py_files.items():
            try:
                ast.parse(content, filename=path)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        if errors:
            return GateResult(name='syntax', status=FAILED, method='ast.parse', detail='Syntax errors found:\n' + '\n'.join(errors))

        return GateResult(name='syntax', status=PASSED, method='ast.parse', detail=f'All {len(py_files)} Python files parsed successfully.')

    def _check_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in authored
        has_setup_py = 'setup.py' in authored
        has_setup_cfg = 'setup.cfg' in authored

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(name='build', status=FAILED, method='filesystem', detail='No packaging metadata (pyproject.toml, setup.py, setup.cfg) found.')

        if has_pyproject:
            content = authored['pyproject.toml']
            if tomllib is None:
                return GateResult(name='build', status=SKIPPED, method='tomllib', detail='tomllib/tomli not available to validate pyproject.toml.')

            try:
                data = tomllib.loads(content)
                # Must contain at least one of these tables
                if not any(k in data for k in ('project', 'build-system', 'tool')):
                    return GateResult(name='build', status=FAILED, method='tomllib', detail='pyproject.toml is valid TOML but missing [project], [build-system], or [tool] tables.')
            except Exception as e:
                return GateResult(name='build', status=FAILED, method='tomllib', detail=f'pyproject.toml is malformed: {e}')

        # Try to install
        try:
            # Check if pip is available
            subprocess.run([self.python, '-m', 'pip', '--version'], capture_output=True, timeout=10)

            # Run pip install -e .
            cmd = [self.python, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation']
            result = subprocess.run(cmd, cwd=workdir, capture_output=True, text=True, timeout=self.timeout_s)

            if result.returncode != 0:
                return GateResult(name='build', status=FAILED, method='pip install', detail=f'pip install failed:\n{result.stderr}')

            return GateResult(name='build', status=PASSED, method='pip install', detail='Package installed successfully.')
        except FileNotFoundError:
            return GateResult(name='build', status=SKIPPED, method='pip install', detail='pip not available.')
        except subprocess.TimeoutExpired:
            return GateResult(name='build', status=FAILED, method='pip install', detail='pip install timed out.')
        except Exception as e:
            return GateResult(name='build', status=FAILED, method='pip install', detail=f'pip install error: {e}')

    def _check_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        # Find non-test modules
        modules = []
        for path in authored:
            if path.endswith('.py'):
                basename = os.path.basename(path).lower()
                if 'test' not in basename:
                    # Convert path to module name
                    # Remove .py
                    mod_path = path[:-3]
                    # Replace / with .
                    mod_name = mod_path.replace('/', '.')
                    # Handle __init__.py
                    if mod_name.endswith('.__init__'):
                        mod_name = mod_name[:-9]
                    if mod_name:
                        modules.append(mod_name)

        if not modules:
            return GateResult(name='smoke', status=FAILED, method='import', detail='No non-test modules found to import.')

        # Set up PYTHONPATH
        env = os.environ.copy()
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"
        if 'PYTHONPATH' in env:
            env['PYTHONPATH'] = f"{python_path}:{env['PYTHONPATH']}"
        else:
            env['PYTHONPATH'] = python_path

        # Try importing each module
        failures = []
        skipped_reasons = []

        for mod_name in modules:
            try:
                # Use subprocess to isolate imports
                code = f"import {mod_name}"
                result = subprocess.run(
                    [self.python, '-c', code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=10
                )
                if result.returncode != 0:
                    stderr = result.stderr
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package
                        # Simple heuristic: if the missing module is not in our authored files
                        # and not a standard library module (hard to check perfectly)
                        # We'll assume if it's not one of our modules, it might be third-party
                        # But we need to be careful. If our module imports a missing third-party,
                        # it's a skip. If our module itself is missing (shouldn't happen), it's fail.

                        # Extract missing module name
                        match = re.search(r"No module named '([^']+)'", stderr)
                        if match:
                            missing_mod = match.group(1)
                            # If the missing module is not one of our authored modules,
                            # and not a standard lib (rough check), treat as skip
                            # For simplicity, if it's not in our authored list, we skip
                            if missing_mod not in modules and not missing_mod.startswith('hae'):
                                skipped_reasons.append(f"{mod_name}: Missing third-party dependency '{missing_mod}'")
                                continue
                    failures.append(f"{mod_name}: {stderr.strip()}")
            except Exception as e:
                failures.append(f"{mod_name}: {e}")

        if failures:
            return GateResult(name='smoke', status=FAILED, method='import', detail='Import failures:\n' + '\n'.join(failures))

        if skipped_reasons:
            return GateResult(name='smoke', status=SKIPPED, method='import', detail='Skipped due to missing dependencies:\n' + '\n'.join(skipped_reasons))

        return GateResult(name='smoke', status=PASSED, method='import', detail=f'All {len(modules)} modules imported successfully.')

    def _check_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        # Find test files
        test_files = []
        for path in authored:
            if path.endswith('.py'):
                basename = os.path.basename(path).lower()
                if 'test' in basename:
                    test_files.append(path)

        if not test_files:
            return GateResult(name='tests', status=FAILED, method='discover', detail='No test files found.')

        # Set up PYTHONPATH
        env = os.environ.copy()
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"
        if 'PYTHONPATH' in env:
            env['PYTHONPATH'] = f"{python_path}:{env['PYTHONPATH']}"
        else:
            env['PYTHONPATH'] = python_path

        # Try pytest first
        try:
            subprocess.run([self.python, '-m', 'pytest', '--version'], capture_output=True, timeout=10)
            # Run pytest
            cmd = [self.python, '-m', 'pytest', '-v'] + test_files
            result = subprocess.run(cmd, cwd=workdir, env=env, capture_output=True, text=True, timeout=self.timeout_s)

            if result.returncode == 0:
                return GateResult(name='tests', status=PASSED, method='pytest', detail='All tests passed.')
            else:
                # Check if it was a collection error due to missing deps
                if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                     # Check if it's a third party
                     # If pytest failed to collect because of missing imports, it might be skip
                     # But pytest usually reports errors. If it ran and failed, it's fail.
                     # If it couldn't even collect, it might be skip.
                     # Let's look for "error" in output
                     if "error" in result.stderr.lower() and "ModuleNotFoundError" in result.stderr:
                         return GateResult(name='tests', status=SKIPPED, method='pytest', detail='Tests skipped due to missing dependencies.')

                return GateResult(name='tests', status=FAILED, method='pytest', detail=f'Tests failed:\n{result.stdout}\n{result.stderr}')
        except FileNotFoundError:
            pass # pytest not installed, fall back
        except Exception:
            pass # pytest failed to run, fall back

        # Fallback: stdlib unittest / manual execution
        # We need to run a script that imports test files and runs tests
        # This is complex to do in a single subprocess call robustly.
        # We'll write a temporary runner script.

        runner_code = """
import sys
import os
import unittest
import importlib.util
import inspect

def run_tests(test_files):
    loader = unittest.TestLoader()
    suite = unittest.TestSuite()

    for test_file in test_files:
        try:
            # Add directory to path
            dir_path = os.path.dirname(test_file)
            if dir_path not in sys.path:
                sys.path.insert(0, dir_path)

            # Import module
            module_name = os.path.basename(test_file).replace('.py', '')
            spec = importlib.util.spec_from_file_location(module_name, test_file)
            if spec is None or spec.loader is None:
                continue
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)

            # Collect tests
            # 1. unittest.TestCase subclasses
            for name in dir(module):
                obj = getattr(module, name)
                if isinstance(obj, type) and issubclass(obj, unittest.TestCase) and obj.__module__ == module_name:
                    suite.addTest(loader.loadTestsFromTestCase(obj))

            # 2. Bare test_* functions
            for name in dir(module):
                if name.startswith('test_'):
                    obj = getattr(module, name)
                    if callable(obj) and not isinstance(obj, type):
                        # Check if it takes 0 args
                        try:
                            sig = inspect.signature(obj)
                            if len(sig.parameters) == 0:
                                # Wrap in a TestCase
                                class TestWrapper(unittest.TestCase):
                                    def runTest(self):
                                        obj()
                                TestWrapper.__name__ = f'Test_{name}'
                                suite.addTest(TestWrapper())
                        except Exception:
                            pass
        except Exception as e:
            print(f'Error loading {test_file}: {e}', file=sys.stderr)
            sys.exit(1)

    runner = unittest.TextTestRunner(verbosity=2)
    result = runner.run(suite)

    if result.wasSuccessful():
        sys.exit(0)
    else:
        sys.exit(1)

if __name__ == '__main__':
    test_files = sys.argv[1:]
    run_tests(test_files)
"""

        try:
            with tempfile.NamedTemporaryFile(mode='w', suffix='.py', delete=False) as f:
                f.write(runner_code)
                runner_path = f.name

            cmd = [self.python, runner_path] + test_files
            result = subprocess.run(cmd, cwd=workdir, env=env, capture_output=True, text=True, timeout=self.timeout_s)

            os.unlink(runner_path)

            if result.returncode == 0:
                return GateResult(name='tests', status=PASSED, method='unittest', detail='All tests passed.')
            else:
                if 'ModuleNotFoundError' in result.stderr:
                    return GateResult(name='tests', status=SKIPPED, method='unittest', detail='Tests skipped due to missing dependencies.')
                return GateResult(name='tests', status=FAILED, method='unittest', detail=f'Tests failed:\n{result.stdout}\n{result.stderr}')
        except Exception as e:
            return GateResult(name='tests', status=FAILED, method='unittest', detail=f'Test runner error: {e}')

    def _check_telemetry(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        py_files = {p: c for p, c in authored.items() if p.endswith('.py')}

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span', 'start_span', 'get_tracer', 
            'get_tracer_provider', 'set_tracer_provider', 'get_meter'
        }

        for path, content in py_files.items():
            try:
                tree = ast.parse(content, filename=path)
            except SyntaxError:
                continue

            for node in ast.walk(tree):
                # Check for import opentelemetry
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                            has_import = True
                elif isinstance(node, ast.ImportFrom):
                    if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                        has_import = True

                # Check for calls
